INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, location) VALUES ('port-1', 'pcat-cms-1', 'ishoot-case-1', 'Al-Jazeera Gulf Holdings W.L.L. — Cinema Commercial Production', 'مجموعة الجزيرة الخليجية القابضة — إنتاج الأفلام الإعلانية السينمائية', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered across Manama with measurable ROI and strict quality benchmarks.', 'تم التنفيذ في Manama وفق أعلى معايير الجودة والالتزام بالجدول الزمني.', 7000, 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('rev-1', 'Executive Director 1', 'المدير التنفيذي 1', 'Al-Jazeera Gulf Holdings W.L.L.', 'مجموعة الجزيرة الخليجية القابضة', 'Working with ishoot streamlined our operations and exceeded delivery expectations.', 'العمل مع آي شوت ساهم في رفع كفاءة عملياتنا وتجاوز توقعاتنا في التسليم.', 5, true, 1, 2026, now() - interval '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'ishoot-insights-1', 'ishoot Industry Brief #1: Cinema Commercial Production', 'تقرير آي شوت التخصصي #1: إنتاج الأفلام الإعلانية السينمائية', 'Key operational benchmarks and best practices from ishoot in Manama.', 'أبرز المعايير التشغيلية وأفضل الممارسات من آي شوت في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography. Our Cinema Commercial Production division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي. يساعد قسم إنتاج الأفلام الإعلانية السينمائية المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.</p><p>Our Cinema Commercial Production division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.</p><p>يساعد قسم إنتاج الأفلام الإعلانية السينمائية المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'media', '{"media","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '9 days', true, now() - interval '9 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How do we engage ishoot for a new project?', 'كيف يمكننا البدء بمشروع جديد مع آي شوت؟', 'Contact ishoot at hello@ishoot.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر hello@ishoot.bh أو إرسال طلب إلكتروني وسيرد فريق آي شوت خلال يوم عمل واحد.', 'general', true, 1, now()) ON CONFLICT (id) DO NOTHING;
